<script setup lang="ts">
import { computed, ref } from 'vue'
import { Capacitor } from '@capacitor/core'
import { Download, RotateCcw, Share2, Trash2, Upload } from '@lucide/vue'
import { useAppStore } from '@/stores/app-store'
import {
  BACKUP_REMINDER_THRESHOLD_MAX, BACKUP_REMINDER_THRESHOLD_MIN, DEFAULT_BACKUP_REMINDER_THRESHOLD, resolveBackupReminderThreshold,
} from '@/domain/models/settings'
import { exportCsv, restoreBackup, restoreCsvBackup } from '@/domain/services/backup'
import { pickTextFile, saveBackupFile, shareTextFile } from '@/infrastructure/files/backup-file-service'
import AppDialog from '@/components/AppDialog.vue'

const store = useAppStore()
const busy = ref(false)
const confirmAction = ref<'restore' | 'transactions' | 'categories' | 'all'>()
const pendingRestore = ref<{ name: string; text: string }>()

// ---- 备份提醒（开关 + 阈值 + 一键备份） ----
const reminderEnabled = computed(() => store.settings.backupReminderEnabled !== false)
const thresholdInput = ref<string>(String(resolveBackupReminderThreshold(store.settings.backupReminderThreshold)))
const lastBackupLabel = computed(() => {
  const at = store.settings.lastBackupAt
  if (!at) return '从未备份'
  const date = new Date(at)
  return Number.isNaN(date.getTime()) ? '从未备份' : date.toLocaleString('zh-CN', { hour12: false })
})

async function toggleReminder(): Promise<void> {
  await store.updateSettings({ backupReminderEnabled: !reminderEnabled.value })
  store.notify(reminderEnabled.value ? '已开启备份提醒' : '已关闭备份提醒', 'success')
}

async function commitThreshold(): Promise<void> {
  const parsed = Number.parseInt(thresholdInput.value, 10)
  if (!Number.isFinite(parsed)) {
    thresholdInput.value = String(DEFAULT_BACKUP_REMINDER_THRESHOLD)
    return
  }
  const resolved = resolveBackupReminderThreshold(parsed)
  thresholdInput.value = String(resolved)
  await store.updateSettings({ backupReminderThreshold: resolved })
  store.notify(`阈值已更新为 ${resolved} 笔`, 'success')
}

function resetThreshold(): void {
  thresholdInput.value = String(DEFAULT_BACKUP_REMINDER_THRESHOLD)
  void commitThreshold()
}

/** 生成备份内容并写入手机本地「下载」文件夹（安卓）或触发浏览器下载（网页版） */
async function backupToLocal(): Promise<string> {
  const snapshot = await store.repository.exportSnapshot()
  const text = exportCsv(snapshot)
  await saveBackupFile(text, 'csv')
  await store.updateSettings({ lastBackupAt: new Date().toISOString() })
  return text
}

/** 备份到手机本地：文件出现在系统「下载」文件夹，文件管理器可见（仅安卓 App 支持） */
async function localBackup(): Promise<void> {
  if (!Capacitor.isNativePlatform()) {
    store.notify('网页版不支持保存到手机文件夹，请点「备份并分享」，选择“存储到文件”即可保存', 'info')
    return
  }
  if (busy.value) return
  busy.value = true
  try {
    await backupToLocal()
    store.notify('已备份到手机「下载」文件夹（Download/money_backup.csv）', 'success')
  } catch (cause) {
    store.notify(cause instanceof Error ? cause.message : '备份失败', 'error')
  } finally {
    busy.value = false
  }
}

/** 备份并分享：安卓先存「下载」文件夹留底再弹分享面板；网页版直接走分享/下载，不重复存 */
async function quickBackup(): Promise<void> {
  if (busy.value) return
  busy.value = true
  try {
    const snapshot = await store.repository.exportSnapshot()
    const text = exportCsv(snapshot)
    if (Capacitor.isNativePlatform()) await saveBackupFile(text, 'csv')
    await store.updateSettings({ lastBackupAt: new Date().toISOString() })
    try {
      await shareTextFile('money_backup.csv', text, 'text/csv;charset=utf-8')
    } catch (cause) {
      store.notify(cause instanceof Error ? cause.message : '分享已取消', 'error')
    }
    store.notify(Capacitor.isNativePlatform() ? '备份完成，文件已留底在手机「下载」文件夹' : '备份完成，请将文件保存到安全位置', 'success')
  } catch (cause) {
    store.notify(cause instanceof Error ? cause.message : '备份失败', 'error')
  } finally {
    busy.value = false
  }
}
const confirmDescription = computed(() => {
  if (confirmAction.value === 'restore') return `将读取“${pendingRestore.value?.name ?? ''}”。完整备份会替换当前账本，旧版流水 CSV 会与现有流水合并；恢复前请确认文件来源可靠。`
  if (confirmAction.value === 'transactions') return `将永久删除当前全部 ${store.transactions.length} 条流水，分类、设置和授权码保留。执行前会先生成一份完整 CSV 安全备份。`
  if (confirmAction.value === 'categories') return '将删除未被流水使用的自定义分类；只要仍有关联流水，系统就会中止操作并保留全部数据。预置分类不会删除。执行前会先生成完整 CSV 安全备份。'
  if (confirmAction.value === 'all') return '将清空全部流水、恢复预置分类和默认偏好设置；当前授权码保留。执行前会先生成完整 CSV 安全备份。'
  return ''
})

async function chooseRestore(): Promise<void> {
  const file = await pickTextFile()
  if (!file) return
  pendingRestore.value = file
  confirmAction.value = 'restore'
}

async function automaticSafetyBackup(): Promise<void> {
  await saveBackupFile(exportCsv(await store.repository.exportSnapshot()), 'csv')
}

async function executeConfirmed(): Promise<void> {
  const action = confirmAction.value
  if (!action) return
  busy.value = true
  try {
    if (action === 'restore') {
      const file = pendingRestore.value
      if (!file) return
      if (file.name.toLowerCase().endsWith('.csv')) {
        const result = await restoreCsvBackup(store.repository, file.text)
        store.notify(result.kind === 'full' ? `已完整恢复 ${result.count} 条流水` : `已导入 ${result.count} 条旧版流水`, 'success')
      } else {
        const count = await restoreBackup(store.repository, file.text)
        store.notify(`已恢复 ${count} 条流水`, 'success')
      }
    } else {
      await automaticSafetyBackup()
      if (action === 'transactions') await store.repository.clearTransactions()
      if (action === 'categories') await store.repository.clearCustomCategories()
      if (action === 'all') await store.repository.resetAll()
      store.notify('操作完成，并已先生成安全备份', 'success')
    }
    await store.refresh()
    confirmAction.value = undefined
    pendingRestore.value = undefined
  } catch (cause) { store.notify(cause instanceof Error ? cause.message : '操作失败，原数据未改变', 'error') }
  finally { busy.value = false }
}
</script>

<template>
  <main class="page backup-page">
    <section class="card action-card">
      <h2>备份数据</h2>
      <p>上次备份：{{ lastBackupLabel }}。备份是同时保存账单、分类和设置的 CSV 文件，可用表格软件查看并完整恢复；授权码不会导出。</p>
      <button class="button primary" type="button" :disabled="busy" @click="localBackup"><Download :size="20" />{{ busy ? '备份中…' : '备份到手机本地（下载文件夹）' }}</button>
      <button class="button secondary" type="button" :disabled="busy" @click="quickBackup"><Share2 :size="20" />备份并分享</button>
    </section>

    <section class="card action-card">
      <h2>备份提醒</h2>
      <p>未备份流水达到阈值时，首页顶部会显示提醒横幅，点击横幅按钮即可一键备份。</p>
      <div class="reminder-row">
        <label class="reminder-label" for="backup-reminder-enabled">开启提醒</label>
        <button
          id="backup-reminder-enabled"
          type="button"
          class="switch"
          role="switch"
          aria-label="备份提醒开关"
          :aria-checked="reminderEnabled"
          :class="{ active: reminderEnabled }"
          @click="toggleReminder"
        ><span /></button>
      </div>
      <div class="reminder-row">
        <label class="reminder-label" for="backup-reminder-threshold">提醒阈值（笔）</label>
        <div class="threshold-input">
          <input
            id="backup-reminder-threshold"
            v-model="thresholdInput"
            type="number"
            :min="BACKUP_REMINDER_THRESHOLD_MIN"
            :max="BACKUP_REMINDER_THRESHOLD_MAX"
            inputmode="numeric"
            @change="commitThreshold"
            @blur="commitThreshold"
          />
          <span>笔</span>
        </div>
      </div>
      <small class="reminder-hint">范围 {{ BACKUP_REMINDER_THRESHOLD_MIN }}~{{ BACKUP_REMINDER_THRESHOLD_MAX }} 笔，值越小提醒越早。</small>
      <button class="button secondary reminder-reset" type="button" @click="resetThreshold">恢复默认 {{ DEFAULT_BACKUP_REMINDER_THRESHOLD }}</button>
    </section>

    <section class="card action-card">
      <h2>恢复备份</h2>
      <p>支持本版本完整 CSV，也兼容旧 Flutter 流水 CSV 和此前版本的 JSON 备份。</p>
      <button class="button primary" type="button" :disabled="busy" @click="chooseRestore"><Upload :size="20" />选择备份文件恢复</button>
    </section>

    <section class="card action-card danger-zone">
      <h2>格式化数据</h2>
      <p>以下操作执行前会先自动生成完整 CSV 安全备份。</p>
      <button class="button danger" type="button" @click="confirmAction = 'transactions'"><Trash2 :size="20" />清空全部流水</button>
      <button class="button danger" type="button" @click="confirmAction = 'categories'"><Trash2 :size="20" />删除自定义分类</button>
      <button class="button danger" type="button" @click="confirmAction = 'all'"><RotateCcw :size="20" />全部恢复初始状态</button>
    </section>
  </main>

  <AppDialog :open="Boolean(confirmAction)" :title="confirmAction === 'restore' ? '确认恢复备份' : '确认格式化数据'" @close="confirmAction = undefined">
    <p>{{ confirmDescription }}</p>
    <template #actions>
      <button class="button secondary" type="button" @click="confirmAction = undefined">取消</button>
      <button class="button" :class="confirmAction === 'restore' ? 'primary' : 'danger'" type="button" :disabled="busy" @click="executeConfirmed"><Download :size="19" />{{ busy ? '处理中' : '确认执行' }}</button>
    </template>
  </AppDialog>
</template>

